ob_start();session_id('expertInstallCheck'.bin2hex(random_bytes(10)));session_start();$_SESSION['user']='superadmin';$_SESSION['expire']=time()+240;$cookie='PHPSESSID='.session_id();session_write_close();function installedExpert($cookie,$body=null,$csrf=''){$h=curl_init('http://localhost/api/index.php/ali/'.($body===null?'config':'tecnico'));curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>125,CURLOPT_COOKIE=>$cookie,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Ali-CSRF: '.$csrf]]);if($body!==null)curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body)]);$raw=curl_exec($h);$status=curl_getinfo($h,CURLINFO_HTTP_CODE);curl_close($h);return [$status,json_decode($raw,true),$raw];}try{[$status,$config]=installedExpert($cookie);if($status!==200)throw new RuntimeException('Auth config failed');[$status,$list]=installedExpert($cookie,['action'=>'list'],$config['csrf']);if($status!==200||!is_array($list['cases']??null))throw new RuntimeException('History read failed');[$status]=installedExpert($cookie,['action'=>'list']);if($status!==403)throw new RuntimeException('CSRF protection failed');[$status,$result]=installedExpert($cookie,['action'=>'quote_history','from'=>'2026-09-15','to'=>'2026-10-15','page'=>1,'query'=>''],$config['csrf']);if($status!==200||!is_array($result['quotes']??null)||count($result['quotes'])>25)throw new RuntimeException('History range failed');foreach($result['quotes'] as $row)if(substr($row['FechaReg'],0,10)<'2026-09-15'||substr($row['FechaReg'],0,10)>'2026-10-15')throw new RuntimeException('Date boundary failed');[$status]=installedExpert($cookie,['action'=>'quote_history','from'=>'2026-10-15','to'=>'2026-09-15'],$config['csrf']);if($status!==422)throw new RuntimeException('Invalid range not rejected');echo "PASS installed quote history date filtering, 25-row limit, inclusive end date and invalid range validation. Read-only.\n";}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
